replace_exact(
    SHOT_DIRECTOR,
    '''export const CreativeShotDirectorRuntime = {\n  async direct({\n''',
    '''export const CreativeShotDirectorRuntime = {\n  async replanStructure({\n    organization_id,\n    organization = {},\n    brand = {},\n    industry = null,\n    objective = "",\n    brief = {},\n    assets = [],\n    requestedOutputs = [],\n    durationSeconds = 30,\n    platform = "multi-channel",\n    budgetMode = "quality-first",\n    productionSpecification = null,\n    currentPlan = {},\n    structuralFailure = {},\n  } = {}) {\n    if (!organization_id) {\n      throw directorError("organization_id required");\n    }\n\n    const evidenceAssets = compactAssets(assets);\n    const freedom = resolveCreativeFreedomPolicy(\n      organization,\n      brand,\n      brief,\n      brief.quality_policy,\n      brief.creative_policy,\n    );\n    const specification =\n      compileCreativeProductionSpecification({\n        organization_id,\n        input: {\n          organization,\n          brand,\n          industry,\n          objective,\n          brief,\n          requested_outputs: requestedOutputs,\n          target_duration_seconds:\n            durationSeconds,\n          platform,\n          budget_mode: budgetMode,\n          production_specification:\n            productionSpecification,\n        },\n        assets: evidenceAssets,\n        existing: productionSpecification,\n      });\n    const input = {\n      organization_id,\n      organization,\n      brand,\n      industry,\n      objective,\n      brief,\n      assets: evidenceAssets,\n      requested_outputs: requestedOutputs,\n      target_duration_seconds:\n        specification.target_duration_seconds,\n      platform,\n      budget_mode: budgetMode,\n      creative_policy: freedom,\n      production_specification:\n        specification,\n    };\n    const execution = await directOnce({\n      input,\n      freedom,\n      structuralReplan: {\n        currentPlan,\n        failure: structuralFailure,\n      },\n    });\n    const plan = normalizePlan({\n      result: execution?.result,\n      reasoning: execution,\n      objective,\n      brief,\n      assets: evidenceAssets,\n      durationSeconds:\n        specification.target_duration_seconds,\n      freedom,\n      repairApplied: true,\n    });\n    const report =\n      assertCreativePlanMatchesProductionSpecification({\n        plan,\n        specification,\n      });\n\n    return {\n      plan: {\n        ...plan,\n        production_specification:\n          specification,\n        metadata: {\n          ...object(plan.metadata),\n          production_specification_key:\n            specification.specification_key,\n          production_specification_report:\n            report,\n          structural_replan_applied: true,\n        },\n      },\n      execution,\n      report,\n    };\n  },\n\n  async direct({\n''',
)

replace_exact(
    JOB_RUNTIME,
    '''  async get({ job_id, organization_id, include_plan = false } = {}) {\n''',
    '''  async replanStructure({\n    job_id,\n    organization_id,\n    reason = null,\n  } = {}) {\n    const job = await getJobRow(job_id);\n\n    if (\n      organization_id &&\n      job.organization_id !== organization_id\n    ) {\n      throw jobError(\n        "CREATIVE_DIRECTOR_JOB_NOT_IN_ORGANIZATION",\n      );\n    }\n\n    const input = object(job.input_snapshot);\n    const assets = list(job.asset_snapshot);\n    const pipeline = object(job.pipeline_result);\n    const replanHistory = list(\n      pipeline.structural_replans,\n    );\n\n    if (replanHistory.length >= 2) {\n      throw jobError(\n        "CREATIVE_DIRECTOR_STRUCTURAL_REPLAN_LIMIT_REACHED",\n        {\n          job_id,\n          structural_replan_count:\n            replanHistory.length,\n        },\n      );\n    }\n\n    const replanned =\n      await CreativeShotDirectorRuntime.replanStructure({\n        organization_id: job.organization_id,\n        organization: input.organization || {},\n        brand: input.brand || {},\n        industry: input.industry || null,\n        objective: input.objective || "",\n        brief: input.brief || {},\n        assets,\n        requestedOutputs:\n          input.requested_outputs || [],\n        durationSeconds:\n          input.target_duration_seconds || 30,\n        platform:\n          input.platform || "multi-channel",\n        budgetMode:\n          input.budget_mode || "quality-first",\n        productionSpecification:\n          input.production_specification,\n        currentPlan: object(job.current_plan),\n        structuralFailure:\n          reason || job.error || {},\n      });\n\n    assertCanonicalReferences(\n      replanned.plan,\n      assets,\n      "structural_replan",\n    );\n\n    const steps = await getStepRows(job_id);\n    const restartStep = steps.find(\n      (step) =>\n        step.step_key ===\n        "executive_narrative_editorial",\n    );\n\n    if (!restartStep) {\n      throw jobError(\n        "CREATIVE_DIRECTOR_STRUCTURAL_REPLAN_RESTART_STEP_MISSING",\n      );\n    }\n\n    const resetKeys = STEP_DEFINITIONS\n      .filter(\n        (definition) =>\n          definition.key !== "initial_director",\n      )\n      .map((definition) => definition.key);\n\n    const { error: resetError } =\n      await supabaseAdmin\n        .from(STEPS)\n        .update({\n          status: "WAITING",\n          provider: null,\n          model: null,\n          confidence: null,\n          duration_ms: null,\n          error: null,\n          completed_at: null,\n          updated_at: now(),\n        })\n        .eq("job_id", job_id)\n        .in("step_key", resetKeys);\n\n    if (resetError) throw resetError;\n\n    const replanRecord = {\n      replan_number:\n        replanHistory.length + 1,\n      reason: reason || job.error || null,\n      production_specification_key:\n        input.production_specification\n          ?.specification_key || null,\n      report: replanned.report,\n      provider:\n        replanned.execution?.provider || null,\n      model:\n        replanned.execution?.model || null,\n      created_at: now(),\n    };\n\n    await updateJob(job_id, {\n      current_plan: replanned.plan,\n      status: "WAITING",\n      current_step_key:\n        restartStep.step_key,\n      current_step_index:\n        restartStep.step_index,\n      completed_steps: 1,\n      progress_percent:\n        Math.round(\n          1 / STEP_DEFINITIONS.length * 10000,\n        ) / 100,\n      storyboard_audit: {},\n      error: null,\n      lease_token: null,\n      lease_expires_at: null,\n      completed_at: null,\n      pipeline_result: {\n        ...pipeline,\n        temporal_direction: {},\n        final_storyboard_convergence: {},\n        structural_replans: [\n          ...replanHistory,\n          replanRecord,\n        ],\n      },\n    });\n\n    return hydrate(job_id, {\n      includePlan: true,\n    });\n  },\n\n  async get({ job_id, organization_id, include_plan = false } = {}) {\n''',
)

